WITH expected(table_name,name,function_name,enabled) AS (VALUES ('app.user_security_profiles','owner_commit','platform_private.commit_usersecurityprofile','O'),('app.user_security_profiles','physical_guard','platform_private.guard_usersecurityprofile','O'),('app.users','owner_commit','platform_private.commit_user','O'),('app.users','physical_guard','platform_private.guard_user','O')),actual AS (SELECT n.nspname||'.'||c.relname,t.tgname::text,fn.nspname||'.'||p.proname,t.tgenabled::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace fn ON fn.oid=p.pronamespace WHERE n.nspname='app' AND c.relname IN ('users','user_security_profiles') AND NOT t.tgisinternal) SELECT jsonb_build_object('expected_user_trigger_count',4,'actual_user_trigger_count',(SELECT count(*) FROM actual),'exact_user_trigger_set_and_states',NOT EXISTS((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)),'no_project_user_trigger_disabled',NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('app','platform','platform_private') AND NOT t.tgisinternal AND t.tgenabled<>'O'));
